//! 🛂️ Original transition payload grammar is verified cooperatively without hydrating a duplicate semantic owner.
use semio_framework_value_native_owned::native_decoding::NativeDecodeCloseControl;
use protocol::codec::HistoryReadLimits;
use pack::format::RetainedUtf8Cursor;
use semio_framework_value::{ValueError, ValueRefusalKind, RetainedCloneGrant, RetainedCloneProgress, RetirementDemand};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
#[derive(Debug)]
pub struct RetainedHistoryTransitionPayloadValidationReceipt{original:(usize,usize),owner:(u64,Option<u64>)}
impl RetainedHistoryTransitionPayloadValidationReceipt{pub fn validates_original(&self,bytes:&[u8],control:&dyn NativeDecodeCloseControl)->bool{self.original==(bytes.as_ptr()as usize,bytes.len())&&self.owner==(control.ledger_identity(),control.retirement_recipient_identity())}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum RetainedHistoryTransitionPayloadValidationStep{Blocked,Progress,Ready,Closed}
pub struct RetainedHistoryTransitionPayloadValidation{original:(usize,usize),owner:(u64,Option<u64>),limits:HistoryReadLimits,position:usize,program:[u8;12],length:usize,pc:usize,started:bool,repeat:u8,remaining:usize,field:u8,text:Option<(usize,usize)>,text_cursor:usize,text_role:u8,utf8:RetainedUtf8Cursor,input_start:usize,input_index:usize,target:(usize,usize),unique_phase:u8,prior_index:usize,prior_position:usize,prior_range:(usize,usize),compare_position:usize,closing:bool,closed:bool,receipt:Option<(RetainedCloneGrant,RetainedCloneProgress)>}
fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn scalar(bytes:&[u8],position:&mut usize)->Result<usize,ValueError>{let mut value=0u64;for index in 0..10{let byte=*bytes.get(*position).ok_or_else(||fault("original transition payload scalar is truncated"))?;if index==9&&byte>1{return Err(fault("original transition payload scalar overflows"))}*position+=1;value|=u64::from(byte&127)<<(index*7);if byte&128==0{return usize::try_from(value).map_err(|_|fault("original transition payload scalar exceeds platform"))}}Err(fault("original transition payload scalar is unbounded"))}
fn range(bytes:&[u8],position:&mut usize,maximum:usize)->Result<(usize,usize),ValueError>{let count=scalar(bytes,position)?;if count>maximum{return Err(fault("original transition payload field exceeds declared bound"))}let start=*position;let end=start.checked_add(count).filter(|end|*end<=bytes.len()).ok_or_else(||fault("original transition payload field is truncated"))?;*position=end;Ok((start,end))}
impl RetainedHistoryTransitionPayloadValidation{
 pub fn admit(bytes:&[u8],limits:HistoryReadLimits,control:&NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<Option<Self>,ValueError>{limits.validate()?;if bytes.len()>limits.maximum_binary_bytes as usize{return Err(fault("original transition payload exceeds binary policy"))}if g.maximum_items==0||g.maximum_depth==0{return Ok(None)}Ok(Some(Self{original:(bytes.as_ptr()as usize,bytes.len()),owner:(control.ledger_identity(),control.retirement_recipient_identity()),limits,position:0,program:[0;12],length:0,pc:0,started:false,repeat:0,remaining:0,field:0,text:None,text_cursor:0,text_role:0,utf8:RetainedUtf8Cursor::default(),input_start:0,input_index:0,target:(0,0),unique_phase:0,prior_index:0,prior_position:0,prior_range:(0,0),compare_position:0,closing:false,closed:false,receipt:Some((g,RetainedCloneProgress{copied_items:1,..Default::default()}))}))}
 fn validate(&self,bytes:&[u8],control:&dyn NativeDecodeCloseControl)->Result<(),ValueError>{if self.original!=(bytes.as_ptr()as usize,bytes.len())||self.owner!=(control.ledger_identity(),control.retirement_recipient_identity()){return Err(fault("original transition payload changed borrowed input or receiving owner"))}Ok(())}
 fn publish(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.receipt=Some((g,p));if !p.fits(g){return Err(fault("original transition payload receipt exceeded caller grant").with_retained_progress(p))}Ok(())}
 pub fn take_receipt(&mut self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt.take()}
 pub fn receipt(&self)->Option<(RetainedCloneGrant,RetainedCloneProgress)>{self.receipt}
 pub fn consumed_end(&self)->usize{self.position}
 pub fn is_ready(&self)->bool{self.started&&self.pc==self.length&&self.position==self.original.1&&self.repeat==0&&self.text.is_none()&&self.unique_phase==0&&self.receipt.is_none()&&!self.closed&&!self.closing}
 pub fn demands(&self,bytes:&[u8],control:&dyn NativeDecodeCloseControl,body:usize)->Result<RetirementDemand,ValueError>{self.validate(bytes,control)?;if self.closed||self.receipt.is_some(){return Ok(Default::default())}let remaining=if self.closing{0}else if let Some((_,end))=self.text{end-self.text_cursor}else if self.unique_phase==2{self.target.1-self.target.0-self.compare_position}else{0};Ok(RetirementDemand{copy_bytes:body.min(remaining).max(usize::from(remaining>0)),depth:1,..Default::default()})}
 fn finish_field(&mut self){if self.repeat==0{self.pc+=1}else{self.field+=1;let fields=match self.repeat{3=>1,4=>3,5=>2,6=>4,_=>0};if self.field==fields{self.field=0;self.remaining-=1;if self.repeat==6{self.input_index+=1}}}}
 fn start_text(&mut self,bytes:&[u8],optional:bool,role:u8)->Result<(),ValueError>{if optional{let tag=*bytes.get(self.position).ok_or_else(||fault("original transition payload option tag is absent"))?;self.position+=1;match tag{0=>{self.finish_field();return Ok(())},1=>{},_=>return Err(fault("original transition payload option tag is invalid"))}}let maximum=if role==2{(self.limits.maximum_text_bytes as usize).min(protocol::SUPERSEDE_SCOPE_MAX_BYTES)}else{self.limits.maximum_text_bytes as usize};let value=range(bytes,&mut self.position,maximum)?;self.text=Some(value);self.text_cursor=value.0;self.text_role=role;self.utf8=RetainedUtf8Cursor::default();Ok(())}
 fn unique_step(&mut self,bytes:&[u8],body:usize)->Result<(),ValueError>{if self.prior_index==self.input_index{self.unique_phase=0;self.field=1;return Ok(())}if self.unique_phase==1{let mut position=self.prior_position;let previous=range(bytes,&mut position,self.limits.maximum_text_bytes as usize)?;let tag=*bytes.get(position).ok_or_else(||fault("original transition prior replacement is absent"))?;position+=1;match tag{0=>{range(bytes,&mut position,self.limits.maximum_text_bytes as usize)?;range(bytes,&mut position,(self.limits.maximum_binary_bytes as usize).min(protocol::SUPERSEDE_PAYLOAD_MAX_BYTES))?;},1=>{},_=>return Err(fault("original transition prior replacement tag is invalid"))}self.prior_position=position;self.prior_range=previous;self.compare_position=0;if previous.1-previous.0!=self.target.1-self.target.0{self.prior_index+=1}else{self.unique_phase=2}return Ok(())}let count=body.min(self.target.1-self.target.0-self.compare_position);for index in self.compare_position..self.compare_position+count{if bytes[self.target.0+index]!=bytes[self.prior_range.0+index]{self.prior_index+=1;self.unique_phase=1;return Ok(())}}self.compare_position+=count;if self.compare_position==self.target.1-self.target.0{return Err(fault("original transition Supersede repeats target"))}Ok(())}
 pub fn step(&mut self,bytes:&[u8],control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedHistoryTransitionPayloadValidationStep,ValueError>{self.validate(bytes,control)?;if self.closed||self.closing||self.receipt.is_some(){return Ok(RetainedHistoryTransitionPayloadValidationStep::Blocked)}if self.is_ready(){return Ok(RetainedHistoryTransitionPayloadValidationStep::Ready)}let d=self.demands(bytes,control,g.maximum_copy_bytes)?;if g.maximum_items==0||g.maximum_depth<d.depth||g.maximum_copy_bytes<d.copy_bytes||g.maximum_capacity_bytes<d.capacity_bytes||g.maximum_release_bytes<d.release_bytes{return Ok(RetainedHistoryTransitionPayloadValidationStep::Blocked)}control.checkpoint()?;let result=self.step_inner(bytes,g.maximum_copy_bytes);let progress=RetainedCloneProgress{copied_items:1,..Default::default()};self.publish(g,progress)?;if let Err(error)=result{self.cancel();return Err(error.with_retained_progress(progress))}Ok(RetainedHistoryTransitionPayloadValidationStep::Progress)}
 fn step_inner(&mut self,bytes:&[u8],body:usize)->Result<(),ValueError>{if self.unique_phase!=0{return self.unique_step(bytes,body)}if let Some((_,end))=self.text{let next=self.text_cursor.saturating_add(body).min(end);let mut utf8=self.utf8;for(index,byte)in bytes[self.text_cursor..next].iter().enumerate(){utf8.admit(*byte,(self.text_cursor+index)as u64).map_err(|_|ValueError::literal(ValueRefusalKind::InvalidValue,"original wire text is not UTF8"))?;}self.utf8=utf8;self.text_cursor=next;if next==end{if !self.utf8.complete(){return Err(fault("original transition payload UTF8 is truncated"))}let value=self.text.take().unwrap();if self.text_role==1{self.target=value;self.unique_phase=1;self.prior_index=0;self.prior_position=self.input_start}else{self.finish_field()}}return Ok(())}if !self.started{let tag=scalar(bytes,&mut self.position)?;let program:&[u8]=match tag{0|1=>&[3],2=>&[1,2,1,3,2,1,4,2,1,2],3=>&[1,1,1],4=>&[1,2],5=>&[1,1,5],6=>&[7,6],_=>return Err(fault("original transition payload tag is unknown"))};self.program[..program.len()].copy_from_slice(program);self.length=program.len();self.started=true;return Ok(())}if self.pc==self.length{if self.position!=bytes.len(){return Err(fault("original transition payload has trailing bytes"))}return Ok(())}let token=self.program[self.pc];if self.repeat==0&&matches!(token,3|4|5|6){let count=scalar(bytes,&mut self.position)?;if count>bytes.len()-self.position||count>self.limits.maximum_fields as usize{return Err(fault("original transition payload list count exceeds declared bound"))}if token==6&&count==0{return Err(fault("original transition Supersede names no input"))}self.repeat=token;self.remaining=count;self.field=0;if token==6{self.input_start=self.position;self.input_index=0}return Ok(())}if self.repeat!=0&&self.remaining==0{self.repeat=0;self.pc+=1;return Ok(())}if self.repeat==6{match self.field{0=>return self.start_text(bytes,false,1),1=>{let tag=*bytes.get(self.position).ok_or_else(||fault("original transition replacement tag is absent"))?;self.position+=1;match tag{0=>self.field=2,1=>{self.field=0;self.remaining-=1;self.input_index+=1},_=>return Err(fault("original transition replacement tag is invalid"))}return Ok(())},2=>return self.start_text(bytes,false,0),3=>{range(bytes,&mut self.position,(self.limits.maximum_binary_bytes as usize).min(protocol::SUPERSEDE_PAYLOAD_MAX_BYTES))?;self.finish_field();return Ok(())},_=>return Err(fault("original transition input frontier is invalid"))}}let optional=token==2||token==7||self.repeat==4&&self.field==2;self.start_text(bytes,optional,if token==7{2}else{0})}
 pub fn take_validated_into(&mut self,bytes:&[u8],control:&NativeDecodeControl<'_>,recipient:&mut Option<RetainedHistoryTransitionPayloadValidationReceipt>,g:RetainedCloneGrant)->Result<bool,ValueError>{self.validate(bytes,control)?;if !self.is_ready()||recipient.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(false)}*recipient=Some(RetainedHistoryTransitionPayloadValidationReceipt{original:self.original,owner:self.owner});self.closed=true;self.publish(g,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(true)}
 pub fn cancel(&mut self){self.closing=true}
 pub fn close_step(&mut self,bytes:&[u8],control:&dyn NativeDecodeCloseControl,g:RetainedCloneGrant)->Result<RetainedHistoryTransitionPayloadValidationStep,ValueError>{self.validate(bytes,control)?;if self.closed{return Ok(RetainedHistoryTransitionPayloadValidationStep::Closed)}if !self.closing||self.receipt.is_some()||g.maximum_items==0||g.maximum_depth==0{return Ok(RetainedHistoryTransitionPayloadValidationStep::Blocked)}self.text=None;self.unique_phase=0;self.closed=true;self.publish(g,RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(RetainedHistoryTransitionPayloadValidationStep::Closed)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.receipt.is_none()&&self.text.is_none()&&self.unique_phase==0}
}
impl Drop for RetainedHistoryTransitionPayloadValidation{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"original transition grammar abandoned receiving metadata")}}
